llm.raw_content:
{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C17"],
      "claim": "Prochlorperazine, the closest phenothiazine analogue (Morgan 0.4921), had absolute oral bioavailability of 12.5 ± 4.3% (range 4.8–25.3%) in healthy volunteers, below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Fluphenazine, a phenothiazine with a trifluoromethyl substituent and piperazine side chain, showed mean absolute oral bioavailability of 4.80% in healthy volunteers.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Trifluoperazine, a phenothiazine with trifluoromethyl and N-methylpiperazine, had small and erratic systemic bioavailability (mean 6.0%, range 2–8%) in patients.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Levomepromazine, a phenothiazine with methoxy and dimethylamino-propyl side chain, is reported with F 30–70%, which would support higher bioavailability, but its lower similarity and different polar substituents limit transfer.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C19"],
      "claim": "Pridopidine, a non-phenothiazine methylsulfonyl-phenyl piperidine, showed high oral availability in humans; this is contradictory but structurally distant from the phenothiazine core.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The closest and most transferable experimental evidence comes from phenothiazine antipsychotics: prochlorperazine, fluphenazine, and trifluoperazine all have absolute oral bioavailability below 20% (2.7–12.5%). The query shares the phenothiazine core, propylamine linker, and polar substituent, making low bioavailability the better-supported prediction. Higher-F analogues are structurally more distant and do not outweigh this consistent low-F pattern.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule was retrieved.",
    "First-pass metabolism, efflux transport, and formulation effects for the query are not directly characterized.",
    "The closest analogues are not identical; differences in the methylsulfonyl and piperidine-carboxamide substituents could alter bioavailability."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

